  const syncData = useCallback(async () => {
    if (!supabase) return;
    setIsSyncing(true);
    try {
      const grosToSync = gros.map(computeGrosFields);
      const sitewebToSync = siteweb.map(computeSitewebFields);
      const inventoryToSync = inventory.map(computeInventoryFields);
      const marketingToSync = marketingServices.map(computeMarketingFields);

      await Promise.all([
        supabase.from('commandes_gros').upsert(grosToSync),
        supabase.from('commandes_siteweb').upsert(sitewebToSync),
        supabase.from('offres').upsert(offres),
        supabase.from('inventory').upsert(inventoryToSync),
        supabase.from('charges').upsert(charges),
        supabase.from('marketing_services').upsert(marketingToSync),
        supabase.from('marketing_spends').upsert(marketingSpends)
      ]);
      const now = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
      setLastSynced(now);
      localStorage.setItem('merch_dz_last_sync', now);
    } catch (e) { console.error("Sync Failed", e); }
    finally { setTimeout(() => setIsSyncing(false), 800); }
  }, [gros, siteweb, offres, inventory, charges, marketingServices, marketingSpends]);

  const login = useCallback(() => true, []);
