        updatedItem = { ...i, [field]: value };
        return updatedItem;
      }
      return i;
    }));
    if (supabase && updatedItem) {
      const payload = computeGrosFields(updatedItem);
      await supabase.from('commandes_gros').update(payload).eq('id', id);
