      id: generateId(), reference: `G${maxRefNum + 1}`, client_name: '', client_phone: '', 
      date_created: new Date().toISOString().split('T')[0], prix_achat_article: 0, 
      impression: false, prix_impression: 0, prix_vente: 0, status: GrosStatus.EN_PRODUCTION, stock_note: '' 
    };
    if (supabase) {
      const payload = computeGrosFields(newRecord);
      const { data, error } = await supabase.from('commandes_gros').insert([payload]).select();
      if (!error && data) setGros(prev => [data[0], ...prev]);
      else setGros(prev => [newRecord, ...prev]);
    } else setGros(prev => [newRecord, ...prev]);
  }, [gros]);

  const deleteGros = useCallback(async (id: string) => {
    if (supabase) await supabase.from('commandes_gros').delete().eq('id', id);
    setGros(prev => prev.filter(item => String(item.id) !== String(id)));
  }, []);

  const updateSiteweb = useCallback(async (id: string, field: keyof CommandeSiteweb, value: any) => {
    let updatedItem: CommandeSiteweb | null = null;
    setSiteweb(p => p.map(i => {
      if (String(i.id) === String(id)) {
        updatedItem = { ...i, [field]: value };
        return updatedItem;
      }
      return i;
    }));
    if (supabase && updatedItem) {
      const payload = computeSitewebFields(updatedItem);
      await supabase.from('commandes_siteweb').update(payload).eq('id', id);
    }
  }, []);

  const addSiteweb = useCallback(async () => {
    const newRecord: CommandeSiteweb = { 
      id: generateId(), reference: String(Date.now()).slice(-6), 
      date_created: new Date().toISOString().split('T')[0], cout_article: 0, cout_impression: 0, 
      prix_vente: 0, status: SitewebStatus.EN_LIVRAISON, stock_note: '', 
      vendeur_name: 'V-X', vendeur_benefice: 0 
    };
    if (supabase) {
      const payload = computeSitewebFields(newRecord);
      const { data, error } = await supabase.from('commandes_siteweb').insert([payload]).select();
      if (!error && data) setSiteweb(prev => [data[0], ...prev]);
      else setSiteweb(prev => [newRecord, ...prev]);
    } else setSiteweb(prev => [newRecord, ...prev]);
  }, []);

  const duplicateSiteweb = useCallback(async (id: string) => {
    const target = siteweb.find(i => String(i.id) === String(id));
    if (target) {
      const newRecord = { ...target, id: generateId(), reference: target.reference + '-copy' };
      if (supabase) {
        const payload = computeSitewebFields(newRecord);
        const { data } = await supabase.from('commandes_siteweb').insert([payload]).select();
        if (data) setSiteweb(prev => [data[0], ...prev]);
      } else setSiteweb(p => [newRecord, ...p]);
    }
  }, [siteweb]);

  const deleteSiteweb = useCallback(async (id: string) => {
    if (supabase) await supabase.from('commandes_siteweb').delete().eq('id', id);
    setSiteweb(prev => prev.filter(item => String(item.id) !== String(id)));
  }, []);

  const updateInventory = useCallback(async (id: string, field: keyof InventoryItem, value: any) => {
    let updatedItem: InventoryItem | null = null;
    setInventory(p => p.map(i => {
      if (String(i.id) === String(id)) {
        updatedItem = { ...i, [field]: value };
        return updatedItem;
      }
      return i;
    }));
    if (supabase && updatedItem) {
      const payload = computeInventoryFields(updatedItem);
      await supabase.from('inventory').update(payload).eq('id', id);
    }
  }, []);

  const addInventory = useCallback(async () => {
    const newRecord: InventoryItem = { id: generateId(), name: 'Nouveau Stock', sku: 'SKU-' + Date.now(), quantity: 0, min_stock: 5, unit_cost: 0, supplier: '' };
    if (supabase) {
      const payload = computeInventoryFields(newRecord);
      const { data } = await supabase.from('inventory').insert([payload]).select();
      if (data) setInventory(prev => [data[0], ...prev]);
    } else setInventory(prev => [newRecord, ...prev]);
  }, []);

  const deleteInventory = useCallback(async (id: string) => {
    if (supabase) await supabase.from('inventory').delete().eq('id', id);
    setInventory(prev => prev.filter(item => String(item.id) !== String(id)));
  }, []);

  const updateCharge = useCallback(async (id: string, field: keyof Charge, value: any) => {
    setCharges(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i));
    if (supabase) await supabase.from('charges').update({ [field]: value }).eq('id', id);
  }, []);

  const addCharge = useCallback(async (label: string = 'Autre') => {
    const newRecord: Charge = { id: generateId(), date: new Date().toISOString().split('T')[0], label, montant: 0, note: '' };
    if (supabase) {
      const { data } = await supabase.from('charges').insert([newRecord]).select();
      if (data) setCharges(prev => [data[0], ...prev]);
    } else setCharges(prev => [newRecord, ...prev]);
  }, []);

  const deleteCharge = useCallback(async (id: string) => {
    if (supabase) await supabase.from('charges').delete().eq('id', id);
    setCharges(prev => prev.filter(item => String(item.id) !== String(id)));
  }, []);

  const updateMarketing = useCallback(async (id: string, field: keyof MarketingService, value: any) => {
    let updatedItem: MarketingService | null = null;
    setMarketingServices(p => p.map(i => {
      if (String(i.id) === String(id)) {
        updatedItem = { ...i, [field]: value };
        return updatedItem;
      }
      return i;
    }));
    if (supabase && updatedItem) {
      const payload = computeMarketingFields(updatedItem);
      await supabase.from('marketing_services').update(payload).eq('id', id);
    }
  }, []);

  const addMarketing = useCallback(async () => {
    const newRecord: MarketingService = { id: generateId(), client_name: 'Nouveau Client', service_description: '', date: new Date().toISOString().split('T')[0], revenue: 0, client_charges: 0, status: MarketingStatus.EN_COURS };
    if (supabase) {
      const payload = computeMarketingFields(newRecord);
      const { data } = await supabase.from('marketing_services').insert([payload]).select();
      if (data) setMarketingServices(prev => [data[0], ...prev]);
    } else setMarketingServices(prev => [newRecord, ...prev]);
  }, []);

  const deleteMarketing = useCallback(async (id: string) => {
    if (supabase) await supabase.from('marketing_services').delete().eq('id', id);
