import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { createClient } from '@supabase/supabase-js';
import { 
  CommandeGros, CommandeSiteweb, Offre, InventoryItem, Charge, MarketingService, MarketingSpend,
  CalculatedGros, CalculatedSiteweb, CalculatedMarketing, DashboardData,
  GrosStatus, SitewebStatus, OffreType, OffreCategory, MarketingStatus, MarketingSpendSource, MarketingSpendType
} from './types.ts';
import { INITIAL_GROS, INITIAL_EXTERN, INITIAL_OFFRES } from './constants.ts';

// Helper functions for calculations to ensure consistency between UI and DB
const computeGrosFields = (item: CommandeGros): any => {
  const total_cout = Number(item.prix_achat_article || 0) + Number(item.prix_impression || 0);
  const total_revenu = Number(item.prix_vente || 0);
  const benefice_net = total_revenu - total_cout;
  const marge_percent = total_revenu > 0 ? (benefice_net / total_revenu) * 100 : 0;

  // UI internal derived fields (non-Supabase)
  const profit = total_revenu - total_cout;

  return {
    ...item,
    total_cout,
    total_revenu,
    benefice_net,
    marge_percent,
    // UI mapping for getCalculatedGros
    cost: total_cout,
    profit_encaisse: item.status === GrosStatus.LIVREE_ENCAISSE ? profit : 0,
    profit_attendu: item.status === GrosStatus.LIVREE_NON_ENCAISSE ? profit : 0,
    perte: item.status === GrosStatus.RETOUR ? total_cout : 0
  };
};

const computeSitewebFields = (item: CommandeSiteweb): any => {
  const total_cout = Number(item.cout_article || 0) + Number(item.cout_impression || 0);
  const total_revenu = Number(item.prix_vente || 0);
  const benefice_net = total_revenu - (total_cout + Number(item.vendeur_benefice || 0));
  const marge_percent = total_revenu > 0 ? (benefice_net / total_revenu) * 100 : 0;

  return {
    ...item,
    total_cout,
    total_revenu,
    benefice_net,
    marge_percent,
    // UI mapping
    profit_net: benefice_net
  };
};

const computeMarketingFields = (item: MarketingService): any => {
  const total_cout = Number(item.client_charges || 0);
  const total_revenu = Number(item.revenue || 0);
  const benefice_net = total_revenu - total_cout;

  return {
    ...item,
    total_cout,
    total_revenu,
    benefice_net,
    // UI mapping
    net_profit: item.status === MarketingStatus.TERMINE ? benefice_net : 0
  };
};

const computeInventoryFields = (item: InventoryItem): any => {
  const stock_value = Number(item.quantity || 0) * Number(item.unit_cost || 0);
  return {
    ...item,
    stock_value
  };
};

const getEnvVar = (name: string) => {
  if (typeof import.meta !== 'undefined' && import.meta.env) {
    const viteName = `VITE_${name}`;
    if (import.meta.env[viteName]) return import.meta.env[viteName];
    if (import.meta.env[name]) return import.meta.env[name];
  }
  return (window as any).process?.env?.[name] || '';
};

const SUPABASE_URL = getEnvVar('SUPABASE_URL');
const SUPABASE_KEY = getEnvVar('SUPABASE_ANON_KEY');
const supabase = (SUPABASE_URL && SUPABASE_KEY) ? createClient(SUPABASE_URL, SUPABASE_KEY) : null;

