      const { data, error } = await supabase.from('commandes_gros').insert(cleanData).select();
      if (!error && data) setGros(p => [...data, ...p]);
    } else {
      setGros(p => [...cleanData.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  const importSiteweb = useCallback(async (d: any[]) => {
