  }, []);

  const addMarketing = useCallback(async () => {
    const baseRecord = { client_name: 'Nouveau Client', service_description: '', date: new Date().toISOString().split('T')[0], revenue: 0, client_charges: 0, status: MarketingStatus.EN_COURS };
    if (supabase) {
      const dbPayload = computeMarketingCalculatedFields(baseRecord as MarketingService);
      const { data } = await supabase.from('marketing_services').insert([dbPayload]).select();
      if (data) setMarketingServices(p => [data[0], ...p]);
    } else {
      setMarketingServices(p => [{ ...baseRecord, id: crypto.randomUUID() } as MarketingService, ...p]);
    }
  }, []);

  const updateOffre = useCallback(async (id: string, field: keyof Offre, value: any) => {
    setOffres(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i));
    if (supabase) await supabase.from('offres').update({ [field]: value }).eq('id', id);
  }, []);

  const addOffre = useCallback(async () => {
    const baseRecord = { date: new Date().toISOString().split('T')[0], type: OffreType.REVENUE, montant: 0, category: OffreCategory.OTHER, description: 'Nouveau Mouvement' };
    if (supabase) { 
      const { data } = await supabase.from('offres').insert([baseRecord]).select(); 
      if (data) setOffres(p => [data[0], ...p]); 
    } else {
      setOffres(p => [{ ...baseRecord, id: crypto.randomUUID() } as Offre, ...p]);
    }
  }, []);

  const deleteGros = useCallback(async (id: string) => { if (supabase) await supabase.from('commandes_gros').delete().eq('id', id); setGros(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const deleteSiteweb = useCallback(async (id: string) => { if (supabase) await supabase.from('commandes_siteweb').delete().eq('id', id); setSiteweb(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const deleteOffre = useCallback(async (id: string) => { if (supabase) await supabase.from('offres').delete().eq('id', id); setOffres(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const deleteInventory = useCallback(async (id: string) => { if (supabase) await supabase.from('inventory').delete().eq('id', id); setInventory(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const updateCharge = useCallback(async (id: string, field: keyof Charge, value: any) => { setCharges(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)); if (supabase) await supabase.from('charges').update({ [field]: value }).eq('id', id); }, []);
  const addCharge = useCallback(async (l: string = 'Autre') => { 
    const baseRecord = { date: new Date().toISOString().split('T')[0], label: l, montant: 0, note: '' }; 
    if (supabase) { 
      const { data } = await supabase.from('charges').insert([baseRecord]).select(); 
      if (data) setCharges(p => [data[0], ...p]); 
    } else {
      setCharges(p => [{ ...baseRecord, id: crypto.randomUUID() } as Charge, ...p]);
    }
  }, []);
  const deleteCharge = useCallback(async (id: string) => { if (supabase) await supabase.from('charges').delete().eq('id', id); setCharges(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const deleteMarketing = useCallback(async (id: string) => { if (supabase) await supabase.from('marketing_services').delete().eq('id', id); setMarketingServices(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const updateMarketingSpend = useCallback(async (id: string, field: keyof MarketingSpend, value: any) => { setMarketingSpends(p => p.map(i => String(i.id) === String(id) ? { ...i, [field]: value } : i)); if (supabase) await supabase.from('marketing_spends').update({ [field]: value }).eq('id', id); }, []);
  const addMarketingSpend = useCallback(async () => { 
    const baseRecord = { date_start: new Date().toISOString().split('T')[0], date_end: new Date().toISOString().split('T')[0], source: MarketingSpendSource.GROS, type: MarketingSpendType.ADS, amount: 0, note: '' }; 
    if (supabase) { 
      const { data } = await supabase.from('marketing_spends').insert([baseRecord]).select(); 
      if (data) setMarketingSpends(p => [data[0], ...p]); 
    } else {
      setMarketingSpends(p => [{ ...baseRecord, id: crypto.randomUUID() } as MarketingSpend, ...p]);
    }
  }, []);
  const deleteMarketingSpend = useCallback(async (id: string) => { if (supabase) await supabase.from('marketing_spends').delete().eq('id', id); setMarketingSpends(p => p.filter(i => String(i.id) !== String(id))); }, []);
  const duplicateSiteweb = useCallback(async (id: string) => { 
    const t = siteweb.find(i => String(i.id) === String(id)); 
    if (t) { 
      const { id: _, ...baseRecord } = t;
      const nr = { ...baseRecord, reference: t.reference + '-copy' }; 
      if (supabase) { 
        const dbPayload = computeSitewebCalculatedFields(nr as CommandeSiteweb);
        const { data, error } = await supabase.from('commandes_siteweb').insert([dbPayload]).select(); 
        if (!error && data) setSiteweb(p => [data[0], ...p]); 
      } else {
        setSiteweb(p => [{ ...nr, id: crypto.randomUUID() } as CommandeSiteweb, ...p]);
      }
    } 
  }, [siteweb]);

  const importGros = useCallback(async (d: any[]) => {
    const cleanData = d.map(({ id, ...rest }) => computeGrosCalculatedFields(rest as CommandeGros));
    if (supabase) {
      const { data, error } = await supabase.from('commandes_gros').insert(cleanData).select();
      if (!error && data) setGros(p => [...data, ...p]);
    } else {
      setGros(p => [...cleanData.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  const importSiteweb = useCallback(async (d: any[]) => {
    const cleanData = d.map(({ id, ...rest }) => computeSitewebCalculatedFields(rest as CommandeSiteweb));
    if (supabase) {
      const { data, error } = await supabase.from('commandes_siteweb').insert(cleanData).select();
      if (!error && data) setSiteweb(p => [...data, ...p]);
    } else {
      setSiteweb(p => [...cleanData.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  const importOffres = useCallback(async (d: any[]) => {
    const cleanData = d.map(({ id, ...rest }) => rest);
    if (supabase) {
      const { data, error } = await supabase.from('offres').insert(cleanData).select();
      if (!error && data) setOffres(p => [...data, ...p]);
    } else {
      setOffres(p => [...cleanData.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  const importInventory = useCallback(async (d: any[]) => {
    const cleanData = d.map(({ id, ...rest }) => computeInventoryCalculatedFields(rest as InventoryItem));
    if (supabase) {
      const { data, error } = await supabase.from('inventory').insert(cleanData).select();
      if (!error && data) setInventory(p => [...data, ...p]);
    } else {
      setInventory(p => [...cleanData.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  const importCharges = useCallback(async (d: any[]) => {
    const cleanData = d.map(({ id, ...rest }) => rest);
    if (supabase) {
      const { data, error } = await supabase.from('charges').insert(cleanData).select();
      if (!error && data) setCharges(p => [...data, ...p]);
    } else {
      setCharges(p => [...cleanData.map(i => ({ ...i, id: crypto.randomUUID() })), ...p]);
    }
  }, []);

  // UI SELECTORS (KEEPING UI COMPATIBLE)
  const getCalculatedGros = useCallback((): CalculatedGros[] => gros.map(i => {
    const calc = computeGrosCalculatedFields(i);
    return { 
      ...i, 
      cost: calc.total_cout, 
      profit_encaisse: i.status === GrosStatus.LIVREE_ENCAISSE ? calc.benefice_net : 0, 
      profit_attendu: i.status === GrosStatus.LIVREE_NON_ENCAISSE ? calc.benefice_net : 0, 
      perte: i.status === GrosStatus.RETOUR ? calc.total_cout : 0 
    };
  }), [gros]);

  const getCalculatedSiteweb = useCallback((): CalculatedSiteweb[] => siteweb.map(i => ({ ...i, profit_net: computeSitewebCalculatedFields(i).benefice_net })), [siteweb]);

  const getCalculatedMarketing = useCallback((): CalculatedMarketing[] => marketingServices.map(i => {
    const calc = computeMarketingCalculatedFields(i);
    return { ...i, net_profit: i.status === MarketingStatus.TERMINE ? calc.benefice_net : 0 };
  }), [marketingServices]);

  const getDashboardData = useCallback((startDate?: string, endDate?: string): DashboardData => {
    const cg = getCalculatedGros(); const cs = getCalculatedSiteweb();
    const filter = (d: string) => (!startDate || d >= startDate) && (!endDate || d <= endDate);
    const fcg = cg.filter(i => filter(i.date_created)); const fcs = cs.filter(i => filter(i.date_created));
    const fo = offres.filter(i => filter(i.date)); const fc = charges.filter(i => filter(i.date)); const fm = marketingSpends.filter(i => filter(i.date_start));
    const enc = fcg.reduce((a, c) => a + c.profit_encaisse, 0) + fcs.filter(o => o.status === SitewebStatus.LIVREE).reduce((a, c) => a + c.profit_net, 0);
    const att = fcg.reduce((a, c) => a + c.profit_attendu, 0) + fcs.filter(o => o.status === SitewebStatus.EN_LIVRAISON || o.status === SitewebStatus.LIVREE_NON_ENCAISSEE).reduce((a, c) => a + c.profit_net, 0);
    const per = fcg.reduce((a, c) => a + c.perte, 0) + fcs.filter(o => o.status === SitewebStatus.RETOUR).reduce((a, c) => a + (Number(c.cout_article) + Number(c.cout_impression)), 0);
    const no = fo.reduce((a, c) => c.type === OffreType.REVENUE ? a + Number(c.montant) : a - Number(c.montant), 0);
    const tc = fc.reduce((a, c) => a + Number(c.montant), 0); const tm = fm.reduce((a, c) => a + Number(c.amount), 0);
    return { encaisse_reel: enc, profit_attendu: att, pertes: per, net_offres: no, total_charges: tc, total_marketing_spend: tm, profit_net_final: enc + att + no - per - tc - tm };
  }, [getCalculatedGros, getCalculatedSiteweb, offres, charges, marketingSpends]);

  return (
    <AppContext.Provider value={{ 
      gros, siteweb, offres, inventory, charges, marketingServices, marketingSpends, dashboardDateStart, dashboardDateEnd, setDashboardDateRange,
      isAuthenticated, login, logout, isSyncing, isCloudActive, lastSynced,
      updateGros, addGros, deleteGros, importGros, updateSiteweb, addSiteweb, duplicateSiteweb, deleteSiteweb, importSiteweb,
      updateOffre, addOffre, deleteOffre, importOffres, updateInventory, addInventory, deleteInventory, importInventory,
      updateCharge, addCharge, deleteCharge, importCharges, updateMarketing, addMarketing, deleteMarketing,
      updateMarketingSpend, addMarketingSpend, deleteMarketingSpend, getCalculatedGros, getCalculatedSiteweb, getCalculatedMarketing, getDashboardData, syncData
    }}>
      {isInitialLoaded ? children : null}
    </AppContext.Provider>
  );
};
export const useAppStore = () => { const c = useContext(AppContext); if (!c) throw new Error("Store error"); return c; };

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppStore } from '../store.tsx';
import { Lock, AlertCircle } from 'lucide-react';

const LoginPage: React.FC = () => {
  const [password, setPassword] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState(false);
  const { login, isAuthenticated } = useAppStore();
  const navigate = useNavigate();

  // If already authenticated, skip the login page
  useEffect(() => {
    if (isAuthenticated) {
      navigate('/', { replace: true });
    }
  }, [isAuthenticated, navigate]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    setIsSubmitting(true);
    setError(false);

    try {
      const success = await login(password);
      if (success) {
        navigate('/', { replace: true });
      } else {
        setError(true);
        setPassword('');
      }
    } catch (err) {
      setError(true);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-4">
      <div className="max-w-md w-full bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 p-8 space-y-8 animate-in zoom-in-95 duration-300">
        <div className="text-center space-y-2">
          <div className="mx-auto w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white text-3xl font-black mb-6 shadow-lg shadow-blue-200">
            M
          </div>
          <h1 className="text-2xl font-bold text-slate-800 tracking-tight">Merch By DZ</h1>
          <p className="text-slate-500 text-sm">Système d'exploitation privé. Veuillez vous identifier.</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1">Mot de passe</label>
            <div className="relative">
              <input
                type="password"
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  setError(false);
                }}
                disabled={isSubmitting}
                className={`w-full pl-12 pr-4 py-4 bg-slate-50 border ${error ? 'border-red-300 focus:ring-red-100' : 'border-slate-200 focus:ring-blue-100'} rounded-2xl outline-none focus:ring-4 focus:border-blue-400 transition-all text-slate-800 font-medium disabled:opacity-50`}
                placeholder="••••••••••••"
                required
              />
              <Lock className={`absolute left-4 top-1/2 -translate-y-1/2 ${error ? 'text-red-400' : 'text-slate-400'}`} size={20} />
            </div>
            {error && (
              <div className="flex items-center gap-2 text-red-500 text-xs font-bold animate-in slide-in-from-top-2 ml-1">
                <AlertCircle size={14} /> Accès refusé. Mot de passe incorrect.
              </div>
            )}
          </div>

          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-200 active:scale-[0.98] disabled:bg-slate-400"
          >
            {isSubmitting ? 'Vérification...' : 'Accéder au Back-Office'}
          </button>
        </form>

        <div className="pt-4 text-center">
          <p className="text-[10px] text-slate-300 font-medium uppercase tracking-tighter">
            © 2025 Merch By DZ • Opérations Sécurisées
          </p>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;

import React, { useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import { 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  BarChart, 
  Bar, 
  Cell, 
  XAxis, 
  YAxis, 
  AreaChart, 
  Area, 
  Line, 
  ComposedChart,
  Legend 
} from 'recharts';
import { Clock, Banknote, Calendar, Wallet, TrendingUp, Megaphone, RotateCcw, BarChart3 } from 'lucide-react';
import { OffreType, MarketingSpendSource, MarketingStatus, GrosStatus, SitewebStatus } from '../types.ts';

const Dashboard: React.FC = () => {
  const { 
    getDashboardData, 
    getCalculatedGros, 
    getCalculatedSiteweb, 
    getCalculatedMarketing, 
    offres, 
    marketingSpends,
    dashboardDateStart,
    dashboardDateEnd,
    setDashboardDateRange
  } = useAppStore();

  const data = getDashboardData(dashboardDateStart, dashboardDateEnd);

  const formatCurrency = (val: number) => val.toLocaleString('fr-DZ') + ' DA';

  // Date Filter Helper
  const filterByDate = (dateStr: string) => {
    if (dashboardDateStart && dateStr < dashboardDateStart) return false;
    if (dashboardDateEnd && dateStr > dashboardDateEnd) return false;
    return true;
  };

  // 1. Time Series Data Processing
  const timeSeriesData = useMemo(() => {
    const dailyMap: Record<string, { 
      date: string, 
      grosProfit: number, 
      retailProfit: number, 
      offresNet: number, 
      marketingProfit: number,
      marketingSpend: number 
    }> = {};

    // Process Gros
    getCalculatedGros().forEach(item => {
      if (!filterByDate(item.date_created)) return;
      const d = item.date_created;
      if (!dailyMap[d]) dailyMap[d] = { date: d, grosProfit: 0, retailProfit: 0, offresNet: 0, marketingProfit: 0, marketingSpend: 0 };
      const profit = item.status === GrosStatus.RETOUR ? -item.cost : (item.prix_vente - item.cost);
      dailyMap[d].grosProfit += profit;
    });

    // Process Retail
    getCalculatedSiteweb().forEach(item => {
      if (!filterByDate(item.date_created)) return;
      const d = item.date_created;
      if (!dailyMap[d]) dailyMap[d] = { date: d, grosProfit: 0, retailProfit: 0, offresNet: 0, marketingProfit: 0, marketingSpend: 0 };
      dailyMap[d].retailProfit += item.profit_net;
    });

    // Process Offres
    offres.forEach(item => {
      if (!filterByDate(item.date)) return;
      const d = item.date;
      if (!dailyMap[d]) dailyMap[d] = { date: d, grosProfit: 0, retailProfit: 0, offresNet: 0, marketingProfit: 0, marketingSpend: 0 };
      const amt = Number(item.montant);
      dailyMap[d].offresNet += item.type === OffreType.REVENUE ? amt : -amt;
    });

    // Process Marketing Services
    getCalculatedMarketing().forEach(item => {
      if (!filterByDate(item.date)) return;
      const d = item.date;
      if (!dailyMap[d]) dailyMap[d] = { date: d, grosProfit: 0, retailProfit: 0, offresNet: 0, marketingProfit: 0, marketingSpend: 0 };
      dailyMap[d].marketingProfit += item.net_profit;
    });

    // Process Marketing Spends
    marketingSpends.forEach(item => {
      if (!filterByDate(item.date_start)) return;
      const d = item.date_start;
      if (!dailyMap[d]) dailyMap[d] = { date: d, grosProfit: 0, retailProfit: 0, offresNet: 0, marketingProfit: 0, marketingSpend: 0 };
      dailyMap[d].marketingSpend += Number(item.amount);
    });

    return Object.values(dailyMap).sort((a, b) => a.date.localeCompare(b.date));
  }, [getCalculatedGros, getCalculatedSiteweb, getCalculatedMarketing, offres, marketingSpends, dashboardDateStart, dashboardDateEnd]);

  // Pillar Stats (Current grouping)
  const pillarStats = useMemo(() => {
    // 1. Gros
    const grosFiltered = getCalculatedGros().filter(item => filterByDate(item.date_created));
    const grosRev = grosFiltered.filter(i => i.status !== GrosStatus.RETOUR).reduce((a, c) => a + c.prix_vente, 0);
    const grosProd = grosFiltered.reduce((a, c) => a + c.cost, 0);
    const grosMarketing = marketingSpends.filter(s => s.source === MarketingSpendSource.GROS && filterByDate(s.date_start)).reduce((a, c) => a + Number(c.amount), 0);

    // 2. Siteweb
    const swFiltered = getCalculatedSiteweb().filter(item => filterByDate(item.date_created));
    const swRev = swFiltered.filter(i => i.status === SitewebStatus.LIVREE).reduce((a, c) => a + Number(c.prix_vente), 0);
    const swProd = swFiltered.filter(i => i.status !== SitewebStatus.RETOUR).reduce((a, c) => a + (Number(c.cout_article) + Number(c.cout_impression) + Number(c.vendeur_benefice)), 0);
    const swMarketing = marketingSpends.filter(s => s.source === MarketingSpendSource.SITEWEB && filterByDate(s.date_start)).reduce((a, c) => a + Number(c.amount), 0);

    // 3. Offres (Subscriptions)
    const offFiltered = offres.filter(item => filterByDate(item.date));
    const offRev = offFiltered.filter(o => o.type === OffreType.REVENUE).reduce((a, c) => a + Number(c.montant), 0);
    const offExp = offFiltered.filter(o => o.type === OffreType.EXPENSE).reduce((a, c) => a + Number(c.montant), 0);
    const offMarketing = marketingSpends.filter(s => s.source === MarketingSpendSource.OFFRES && filterByDate(s.date_start)).reduce((a, c) => a + Number(c.amount), 0);

    // 4. Marketing Client (Services)
    const clientFiltered = getCalculatedMarketing().filter(item => filterByDate(item.date));
    const clientRev = clientFiltered.filter(m => m.status === MarketingStatus.TERMINE).reduce((a, c) => a + Number(m.revenue), 0);
    const clientExp = clientFiltered.filter(m => m.status === MarketingStatus.TERMINE).reduce((a, c) => a + Number(m.client_charges), 0);
    const clientMarketing = marketingSpends.filter(s => s.source === MarketingSpendSource.MARKETING_CLIENT && filterByDate(s.date_start)).reduce((a, c) => a + Number(c.amount), 0);

    return [
      { name: 'Gros', rev: grosRev, exp: grosProd, marketing: grosMarketing, net: grosRev - grosProd - grosMarketing },
      { name: 'Retail', rev: swRev, exp: swProd, marketing: swMarketing, net: swRev - swProd - swMarketing },
      { name: 'Plans', rev: offRev, exp: offExp, marketing: offMarketing, net: offRev - offExp - offMarketing },
      { name: 'Services', rev: clientRev, exp: clientExp, marketing: clientMarketing, net: clientRev - clientExp - clientMarketing },
    ];
  }, [getCalculatedGros, getCalculatedSiteweb, getCalculatedMarketing, offres, marketingSpends, dashboardDateStart, dashboardDateEnd]);

  const kpis = [
    { label: 'Profit Encaissé', value: data.encaisse_reel, icon: Banknote, color: 'text-emerald-600', bg: 'bg-emerald-50' },
    { label: 'Attendu (En cours)', value: data.profit_attendu, icon: Clock, color: 'text-blue-600', bg: 'bg-blue-50' },
    { label: 'Marketing Spend', value: data.total_marketing_spend, icon: Megaphone, color: 'text-purple-600', bg: 'bg-purple-50' },
    { label: 'Fixed Charges', value: data.total_charges, icon: Wallet, color: 'text-orange-600', bg: 'bg-orange-50' },
  ];

  const ChartCard = ({ title, children, icon: Icon, colorClass }: { title: string, children: React.ReactNode, icon: any, colorClass: string }) => (
    <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col h-[380px]">
      <div className="flex items-center gap-3 mb-6">
        <div className={`p-2 rounded-xl ${colorClass.replace('text', 'bg').replace('600', '50')}`}>
          <Icon className={colorClass} size={18} />
        </div>
        <h4 className="font-bold text-slate-800 text-sm tracking-tight">{title}</h4>
      </div>
      <div className="flex-1 min-h-0">
        <ResponsiveContainer width="100%" height="100%">
          {children as any}
        </ResponsiveContainer>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-12">
      {/* Header & Date Filtering */}
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Tableau de Bord</h2>
          <p className="text-slate-500 font-medium italic">Analyse {dashboardDateStart || dashboardDateEnd ? 'filtrée par période' : 'globale de tous les temps'}.</p>
        </div>

        <div className="flex flex-wrap items-center gap-3 p-3 bg-white border border-slate-100 rounded-3xl shadow-sm">
          <div className="flex items-center gap-2 px-3 py-2 bg-slate-50 rounded-2xl border border-slate-100 transition-all hover:border-blue-200">
            <Calendar size={16} className="text-blue-500" />
            <input 
              type="date" 
              value={dashboardDateStart} 
              onChange={(e) => setDashboardDateRange(e.target.value, dashboardDateEnd)} 
              className="bg-transparent border-none text-xs font-black text-slate-800 outline-none w-28" 
            />
            <span className="text-[10px] font-black text-slate-300 uppercase">Au</span>
            <input 
              type="date" 
              value={dashboardDateEnd} 
              onChange={(e) => setDashboardDateRange(dashboardDateStart, e.target.value)} 
              className="bg-transparent border-none text-xs font-black text-slate-800 outline-none w-28" 
            />
          </div>
          {(dashboardDateStart || dashboardDateEnd) && (
            <button 
              onClick={() => setDashboardDateRange('', '')}
