import React, { useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import { 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  AreaChart, 
  Area, 
  Line, 
  ComposedChart,
  Legend,
  Cell
} from 'recharts';
import { 
  Clock, 
  Banknote, 
  Calendar, 
  Wallet, 
  TrendingUp, 
  Megaphone, 
  RotateCcw, 
  BarChart3, 
  ArrowUpRight, 
  ArrowDownRight, 
