  Globe,
  UserCheck,
  Megaphone,
  Cloud,
  Bot,
  RotateCcw,
  X,
  Store,
  PanelLeftClose,
  Banknote,
  CreditCard
} from 'lucide-react';

interface SidebarProps {
  isMobileOpen?: boolean;
  onClose?: () => void;
  isHidden?: boolean;
