}

const Sidebar: React.FC<SidebarProps> = ({ isMobileOpen, onClose, isHidden, onToggle }) => {
  const { isSyncing, isCloudActive, syncData, lastSynced } = useAppStore();

  const renderNavLink = (item: any) => (
    <NavLink
