        <KPICard title="Profit Brut Global" value={globalKPIs.totalProfitNet} icon={TrendingUp} colorClass={{text: 'text-emerald-600', bg: 'bg-emerald-50'}} trend={{ val: trends.profitDelta }} />
        <KPICard title="Livrée Non Encaissée" value={globalKPIs.lneProfit} icon={Clock} colorClass={{text: 'text-purple-600', bg: 'bg-purple-50'}} />
        <KPICard title="Pertes de Retours" value={globalKPIs.retLoss} icon={RotateCcw} colorClass={{text: 'text-red-600', bg: 'bg-red-50'}} trend={{ val: trends.retsDelta }} />
      </div>

      <div className="h-px bg-slate-100 w-full" />

      {/* --- WATERFALL SECTION --- */}
