                    return null;
                  }}
                />
                <Bar dataKey="bottom" stackId="a" fill="transparent" />
                <Bar dataKey="value" stackId="a" radius={[6, 6, 6, 6]}>
                  {waterfallData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
