  Megaphone, 
  RotateCcw, 
  BarChart3, 
  ArrowUpRight, 
  ArrowDownRight, 
  LayoutGrid, 
  Truck, 
  ShoppingBag, 
  Zap,
  Target,
  AlertCircle,
