import React, { useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import { 
  ResponsiveContainer, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip,
  Legend
} from 'recharts';
import { 
  Banknote, 
  Wallet, 
  TrendingUp, 
  RotateCcw, 
  Zap,
  Target
} from 'lucide-react';
import { OffreType, MarketingStatus, GrosStatus, SitewebStatus, MerchStatus } from '../types.ts';

const formatCurrency = (val: number) => val.toLocaleString('fr-DZ') + ' DA';

const KPICard = ({ title, value, subValues = [], icon: Icon, colorClass, statusCount, subtitle }: any) => (
  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between transition-all hover:shadow-md group relative overflow-hidden">
    <div className="flex justify-between items-start mb-6">
      <div className={`p-4 rounded-2xl ${colorClass.bg}`}>
        <Icon className={colorClass.text} size={24} />
      </div>
      {statusCount !== undefined && (
        <span className="bg-slate-50 px-4 py-1.5 rounded-full text-[10px] font-black text-slate-400 border border-slate-100">
          {statusCount} OBJETS
        </span>
      )}
    </div>
    <div>
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
      <h3 className="text-3xl font-black text-slate-900 tracking-tighter">{formatCurrency(value)}</h3>
      {subtitle && <p className="text-[9px] font-bold text-slate-400 italic mt-1">{subtitle}</p>}
    </div>
    {subValues.length > 0 && (
      <div className="grid grid-cols-2 gap-4 mt-6 pt-6 border-t border-slate-50">
        {subValues.map((sv: any, i: number) => (
          <div key={i}>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">{sv.label}</p>
            <p className={`text-[11px] font-bold ${sv.color || 'text-slate-700'}`}>{typeof sv.val === 'number' ? formatCurrency(sv.val) : sv.val}</p>
          </div>
        ))}
      </div>
    )}
  </div>
);

const Dashboard: React.FC = () => {
  const { 
    getDashboardData, 
    getCalculatedGros, 
    getCalculatedSiteweb, 
    getCalculatedMerch,
    getCalculatedMarketing,
    offres,
    dashboardDateStart,
    dashboardDateEnd,
  } = useAppStore();

  const data = getDashboardData(dashboardDateStart, dashboardDateEnd);

  const filterByDate = (dateStr: string) => {
    if (!dateStr) return true;
    const cleanDate = dateStr.split('T')[0];
    if (dashboardDateStart && cleanDate < dashboardDateStart) return false;
    if (dashboardDateEnd && cleanDate > dashboardDateEnd) return false;
    return true;
  };

  const globalKPIs = useMemo(() => {
    const cg = getCalculatedGros().filter(i => filterByDate(i.date_created));
    const cs = getCalculatedSiteweb().filter(i => filterByDate(i.date_created));
    const cm = getCalculatedMerch().filter(i => filterByDate(i.created_at));
    const fo = offres.filter(i => filterByDate(i.date));
    const fm = getCalculatedMarketing().filter(i => filterByDate(i.date));

    const profitGros = cg.filter(i => [GrosStatus.LIVREE_ENCAISSE, GrosStatus.LIVREE_NON_ENCAISSE].includes(i.status)).reduce((a,c) => a + (c.prix_vente - c.cost), 0);
    const profitSW = cs.filter(i => [SitewebStatus.LIVREE, SitewebStatus.LIVREE_NON_ENCAISSEE].includes(i.status)).reduce((a,c) => a + c.profit_net, 0);
    const profitMerch = cm.filter(i => [MerchStatus.LIVREE, MerchStatus.LIVREE_NON_ENCAISSEE].includes(i.status)).reduce((a,c) => a + (c.prix_vente - c.prix_achat), 0);
    const profitOffres = fo.filter(o => o.type === OffreType.REVENUE).reduce((a,c) => a + Number(c.montant), 0) - fo.filter(o => o.type === OffreType.EXPENSE).reduce((a,c) => a + Number(c.montant), 0);

    // Fixed: replaced 'i' with 'c' to correctly use the reduce callback accumulator and current value
    const profitComptoir = fm.filter(i => i.status === MarketingStatus.TERMINE).reduce((a,c) => a + (c.revenue - c.client_charges), 0);

    return { profitGros, profitSW, profitMerch, profitOffres, profitComptoir };
  }, [getCalculatedGros, getCalculatedSiteweb, getCalculatedMerch, getCalculatedMarketing, offres, dashboardDateStart, dashboardDateEnd]);

  const chartData = [
    { name: 'Gros', value: globalKPIs.profitGros },
    { name: 'Siteweb', value: globalKPIs.profitSW },
    { name: 'Merch', value: globalKPIs.profitMerch },
    { name: 'Comptoir', value: globalKPIs.profitComptoir },
  ];

  return (
    <div className="space-y-8 pb-20 animate-in fade-in duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Tableau de Bord</h2>
          <p className="text-slate-500 font-medium">Vue d'ensemble de la performance financière.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <KPICard 
          title="Profit Net Final" 
          value={data.profit_net_final} 
          icon={Zap} 
          colorClass={{ bg: 'bg-blue-50', text: 'text-blue-600' }} 
        />
        <KPICard 
          title="Encaisse Réel" 
          value={data.encaisse_reel} 
          icon={Banknote} 
          colorClass={{ bg: 'bg-emerald-50', text: 'text-emerald-600' }} 
        />
        <KPICard 
          title="Profit Attendu" 
          value={data.profit_attendu} 
          icon={Target} 
          colorClass={{ bg: 'bg-purple-50', text: 'text-purple-600' }} 
        />
        <KPICard 
          title="Pertes" 
          value={data.pertes} 
          icon={RotateCcw} 
          colorClass={{ bg: 'bg-red-50', text: 'text-red-600' }} 
        />
      </div>

      <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm">
        <div className="h-[400px]">
          <h4 className="font-black text-slate-800 text-xs tracking-widest uppercase mb-8">Performance par Canal (Profit Brut)</h4>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip formatter={(value: number) => formatCurrency(value)} />
              <Legend />
              <Bar dataKey="value" fill="#3b82f6" radius={[10, 10, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

