import React, { useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import { 
  ResponsiveContainer, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip,
  Legend
} from 'recharts';
import { 
  Banknote, 
  Wallet, 
  TrendingUp, 
  RotateCcw, 
  Zap,
  Target
} from 'lucide-react';
import { OffreType, MarketingStatus, GrosStatus, SitewebStatus, MerchStatus, MarketingSpendSource } from '../types.ts';

const formatCurrency = (val: number) => val.toLocaleString('fr-DZ') + ' DA';

const KPICard = ({ title, value, subValues = [], icon: Icon, colorClass, statusCount, subtitle }: any) => (
  <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between transition-all hover:shadow-md group relative overflow-hidden">
    <div className="flex justify-between items-start mb-6">
      <div className={`p-4 rounded-2xl ${colorClass.bg}`}>
        <Icon className={colorClass.text} size={24} />
      </div>
      {statusCount !== undefined && (
        <span className="bg-slate-50 px-4 py-1.5 rounded-full text-[10px] font-black text-slate-400 border border-slate-100">
          {statusCount} OBJETS
        </span>
      )}
    </div>
    <div>
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
      <h3 className="text-3xl font-black text-slate-900 tracking-tighter">{formatCurrency(value)}</h3>
      {subtitle && <p className="text-[9px] font-bold text-slate-400 italic mt-1">{subtitle}</p>}
    </div>
    {subValues.length > 0 && (
      <div className="grid grid-cols-2 gap-4 mt-6 pt-6 border-t border-slate-50">
        {subValues.map((sv: any, i: number) => (
          <div key={i}>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">{sv.label}</p>
            <p className={`text-[11px] font-bold ${sv.color || 'text-slate-700'}`}>{typeof sv.val === 'number' ? formatCurrency(sv.val) : sv.val}</p>
          </div>
        ))}
      </div>
    )}
  </div>
);

const Dashboard: React.FC = () => {
  const { 
    getDashboardData, 
    getCalculatedGros, 
    getCalculatedSiteweb, 
    getCalculatedMerch,
    getCalculatedMarketing,
    marketingSpends,
    offres,
    dashboardDateStart,
    dashboardDateEnd,
  } = useAppStore();

  const data = getDashboardData(dashboardDateStart, dashboardDateEnd);

  const filterByDate = (dateStr: string) => {
    if (!dateStr) return true;
    const cleanDate = dateStr.split('T')[0];
    if (dashboardDateStart && cleanDate < dashboardDateStart) return false;
    if (dashboardDateEnd && cleanDate > dashboardDateEnd) return false;
    return true;
  };

  // 🟦 PILLAR: GROS (Wholesale)
  const grosMetrics = useMemo(() => {
    const items = getCalculatedGros().filter(i => filterByDate(i.date_created));
    const ads = marketingSpends.filter(s => s.source === MarketingSpendSource.GROS && filterByDate(s.date_start)).reduce((a, c) => a + Number(c.amount), 0);

    const delivered = items.filter(i => [GrosStatus.LIVREE_ENCAISSE, GrosStatus.LIVREE_NON_ENCAISSE].includes(i.status));
    const rawProfit = delivered.reduce((a, c) => a + (Number(c.prix_vente) - Number(c.cost)), 0);
    const returnLoss = items.filter(i => i.status === GrosStatus.RETOUR).reduce((a, c) => a + Number(c.cost), 0);
    const potentialProfit = items.filter(i => [GrosStatus.EN_LIVRAISON, GrosStatus.EN_PRODUCTION].includes(i.status)).reduce((a, c) => a + (Number(c.prix_vente) - Number(c.cost)), 0);

    return { profitFinal: rawProfit - returnLoss - ads, profitPotentiel: potentialProfit, ads, returnLoss };
  }, [getCalculatedGros, marketingSpends, dashboardDateStart, dashboardDateEnd]);

  // 🟨 PILLAR: VENDEURS (Retail)
  const vendeurMetrics = useMemo(() => {
    const items = getCalculatedSiteweb().filter(i => filterByDate(i.date_created));
    const ads = marketingSpends.filter(s => s.source === MarketingSpendSource.SITEWEB && filterByDate(s.date_start)).reduce((a, c) => a + Number(c.amount), 0);
    const delivered = items.filter(i => [SitewebStatus.LIVREE, SitewebStatus.LIVREE_NON_ENCAISSEE].includes(i.status));
    const rawProfit = delivered.reduce((a, c) => {
      const prodCost = Number(c.cout_article) + Number(c.cout_impression);
      return a + (Number(c.prix_vente) - prodCost - Number(c.vendeur_benefice));
    }, 0);
    const returnLoss = items.filter(i => i.status === SitewebStatus.RETOUR).reduce((a, c) => a + (Number(c.cout_article) + Number(c.cout_impression)), 0);
    return { profitFinal: rawProfit - returnLoss - ads, ads, returnLoss };
  }, [getCalculatedSiteweb, marketingSpends, dashboardDateStart, dashboardDateEnd]);

  // 🟪 PILLAR: MERCH
  const merchMetrics = useMemo(() => {
    const items = getCalculatedMerch().filter(i => filterByDate(i.created_at));
    const ads = marketingSpends.filter(s => s.source === MarketingSpendSource.MERCH && filterByDate(s.date_start)).reduce((a, c) => a + Number(c.amount), 0);
    const delivered = items.filter(i => [MerchStatus.LIVREE, MerchStatus.LIVREE_NON_ENCAISSEE].includes(i.status));
    const rawProfit = delivered.reduce((a, c) => a + (Number(c.prix_vente) - Number(c.prix_achat)), 0);
    const returnLoss = items.filter(i => i.status === MerchStatus.RETOUR).reduce((a, c) => a + Number(c.prix_achat), 0);
    return { profitFinal: rawProfit - returnLoss - ads, ads, returnLoss };
  }, [getCalculatedMerch, marketingSpends, dashboardDateStart, dashboardDateEnd]);

  // 🟩 PILLAR: OFFRES
  const offresMetrics = useMemo(() => {
    const items = offres.filter(i => filterByDate(i.date));
    const ads = marketingSpends.filter(s => s.source === MarketingSpendSource.OFFRES && filterByDate(s.date_start)).reduce((a, c) => a + Number(c.amount), 0);
    const netRevenue = items.reduce((a, c) => a + (c.type === OffreType.REVENUE ? Number(c.montant) : -Number(c.montant)), 0);
    return { profitFinal: netRevenue - ads, ads };
  }, [offres, marketingSpends, dashboardDateStart, dashboardDateEnd]);

  const globalKPIs = useMemo(() => {
    const cg = getCalculatedGros().filter(i => filterByDate(i.date_created));
    const cs = getCalculatedSiteweb().filter(i => filterByDate(i.date_created));
    const cm = getCalculatedMerch().filter(i => filterByDate(i.created_at));
    const fo = offres.filter(i => filterByDate(i.date));
    const fm = getCalculatedMarketing().filter(i => filterByDate(i.date));

    const profitGros = cg.filter(i => [GrosStatus.LIVREE_ENCAISSE, GrosStatus.LIVREE_NON_ENCAISSE].includes(i.status)).reduce((a,c) => a + (c.prix_vente - c.cost), 0);
    const profitSW = cs.filter(i => [SitewebStatus.LIVREE, SitewebStatus.LIVREE_NON_ENCAISSEE].includes(i.status)).reduce((a,c) => a + c.profit_net, 0);
    const profitMerch = cm.filter(i => [MerchStatus.LIVREE, MerchStatus.LIVREE_NON_ENCAISSEE].includes(i.status)).reduce((a,c) => a + (c.prix_vente - c.prix_achat), 0);
    const profitOffres = fo.filter(o => o.type === OffreType.REVENUE).reduce((a,c) => a + Number(c.montant), 0) - fo.filter(o => o.type === OffreType.EXPENSE).reduce((a,c) => a + Number(c.montant), 0);

    const profitComptoir = fm.filter(i => i.status === MarketingStatus.TERMINE).reduce((a,c) => a + (c.revenue - c.client_charges), 0);

    return { profitGros, profitSW, profitMerch, profitOffres, profitComptoir };
  }, [getCalculatedGros, getCalculatedSiteweb, getCalculatedMerch, getCalculatedMarketing, offres, dashboardDateStart, dashboardDateEnd]);

  const chartData = [
    { name: 'Gros', value: globalKPIs.profitGros },
    { name: 'Siteweb', value: globalKPIs.profitSW },
    { name: 'Merch', value: globalKPIs.profitMerch },
    { name: 'Comptoir', value: globalKPIs.profitComptoir },
  ];

  return (
    <div className="space-y-8 pb-20 animate-in fade-in duration-700">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Tableau de Bord</h2>
          <p className="text-slate-500 font-medium">Vue d'ensemble de la performance financière.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <KPICard 
          title="Profit Net Final" 
          value={data.profit_net_final} 
          icon={Zap} 
          colorClass={{ bg: 'bg-blue-50', text: 'text-blue-600' }} 
        />
        <KPICard 
          title="Encaisse Réel" 
          value={data.encaisse_reel} 
          icon={Banknote} 
          colorClass={{ bg: 'bg-emerald-50', text: 'text-emerald-600' }} 
        />
        <KPICard 
          title="Profit Attendu" 
          value={data.profit_attendu} 
          icon={Target} 
          colorClass={{ bg: 'bg-purple-50', text: 'text-purple-600' }} 
        />
        <KPICard 
          title="Pertes" 
          value={data.pertes} 
          icon={RotateCcw} 
          colorClass={{ bg: 'bg-red-50', text: 'text-red-600' }} 
        />
      </div>

      <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm">
        <div className="h-[400px]">
          <h4 className="font-black text-slate-800 text-xs tracking-widest uppercase mb-8">Performance par Canal (Profit Brut)</h4>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip formatter={(value: number) => formatCurrency(value)} />
              <Legend />
              <Bar dataKey="value" fill="#3b82f6" radius={[10, 10, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo } from 'react';
import { useAppStore } from '../store.tsx';
import { 
  ResponsiveContainer, 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  Tooltip,
  Legend,
  ComposedChart,
  Line,
  Area,
  CartesianGrid
} from 'recharts';
import { 
  Banknote, 
  Wallet, 
  TrendingUp, 
  RotateCcw, 
  Zap,
  Target,
  Megaphone,
  Info
} from 'lucide-react';
import { OffreType, MarketingStatus, GrosStatus, SitewebStatus, MerchStatus, MarketingSpendSource } from '../types.ts';

const formatCurrency = (val: number) => val.toLocaleString('fr-DZ') + ' DA';

const KPICard = ({ title, value, subValues = [], icon: Icon, colorClass, statusCount, subtitle, isMuted = false }: any) => (
  <div className={`p-6 rounded-[2rem] border shadow-sm flex flex-col justify-between transition-all hover:shadow-md group relative overflow-hidden ${isMuted ? 'bg-slate-50/50 border-slate-100 border-dashed opacity-80' : 'bg-white border-slate-100'}`}>
    <div className="flex justify-between items-start mb-4">
      <div className={`p-3 rounded-xl ${colorClass.bg}`}>
        <Icon className={colorClass.text} size={20} />
      </div>
      {statusCount !== undefined && (
        <span className="bg-slate-50 px-3 py-1 rounded-full text-[9px] font-black text-slate-400 border border-slate-100">
          {statusCount} OBJETS
        </span>
      )}
    </div>
    <div>
      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
      <h3 className={`text-2xl font-black tracking-tighter ${isMuted ? 'text-slate-500' : 'text-slate-900'}`}>{formatCurrency(value)}</h3>
      {subtitle && <p className="text-[9px] font-bold text-slate-400 italic mt-1">{subtitle}</p>}
    </div>
    {subValues.length > 0 && (
      <div className="grid grid-cols-2 gap-4 mt-4 pt-4 border-t border-slate-50">
        {subValues.map((sv: any, i: number) => (
          <div key={i}>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">{sv.label}</p>
            <p className={`text-[11px] font-bold ${sv.color || 'text-slate-700'}`}>{typeof sv.val === 'number' ? formatCurrency(sv.val) : sv.val}</p>
          </div>
        ))}
      </div>
    )}
  </div>
);

const Dashboard: React.FC = () => {
  const { 
    getDashboardData, 
    getCalculatedGros, 
    getCalculatedSiteweb, 
    getCalculatedMerch,
    getCalculatedMarketing,
    marketingSpends,
    offres,
    dashboardDateStart,
    dashboardDateEnd,
  } = useAppStore();

  const data = getDashboardData(dashboardDateStart, dashboardDateEnd);

  const filterByDate = (dateStr: string) => {
    if (!dateStr) return true;
    const cleanDate = dateStr.split('T')[0];
    if (dashboardDateStart && cleanDate < dashboardDateStart) return false;
    if (dashboardDateEnd && cleanDate > dashboardDateEnd) return false;
    return true;
  };

  // Helper for Chart Data Aggregation
  const getDailySeries = (items: any[], dateField: string, calcFn: (item: any) => number) => {
    const map = new Map();
    items.forEach(item => {
      const d = item[dateField]?.split('T')[0];
      if (d && filterByDate(d)) {
        map.set(d, (map.get(d) || 0) + calcFn(item));
      }
    });
    return Array.from(map.entries()).map(([date, value]) => ({ date, value })).sort((a, b) => a.date.localeCompare(b.date));
  };

  // 🟦 PILLAR: GROS
  const grosMetrics = useMemo(() => {
    const items = getCalculatedGros().filter(i => filterByDate(i.date_created));
    const adsItems = marketingSpends.filter(s => s.source === MarketingSpendSource.GROS && filterByDate(s.date_start));
    const ads = adsItems.reduce((a, c) => a + Number(c.amount), 0);

    const delivered = items.filter(i => [GrosStatus.LIVREE_ENCAISSE, GrosStatus.LIVREE_NON_ENCAISSE].includes(i.status));
    const rawProfit = delivered.reduce((a, c) => a + (Number(c.prix_vente) - Number(c.cost)), 0);
    const returnLoss = items.filter(i => i.status === GrosStatus.RETOUR).reduce((a, c) => a + Number(c.cost), 0);
    const potentialProfit = items.filter(i => [GrosStatus.EN_LIVRAISON, GrosStatus.EN_PRODUCTION].includes(i.status)).reduce((a, c) => a + (Number(c.prix_vente) - Number(c.cost)), 0);

    // Chart Data
    const dailyProfit = getDailySeries(delivered, 'date_created', (i) => Number(i.prix_vente) - Number(i.cost));
    const dailyAds = getDailySeries(adsItems, 'date_start', (i) => Number(i.amount));

    const chartData = dailyProfit.map(p => ({
      date: p.date,
      Profit: p.value,
      Marketing: dailyAds.find(a => a.date === p.date)?.value || 0
    }));

    return { profitFinal: rawProfit - returnLoss - ads, profitPotentiel: potentialProfit, ads, returnLoss, chartData, count: items.length };
  }, [getCalculatedGros, marketingSpends, dashboardDateStart, dashboardDateEnd]);

  // 🟨 PILLAR: VENDEURS
  const vendeurMetrics = useMemo(() => {
    const items = getCalculatedSiteweb().filter(i => filterByDate(i.date_created));
    const adsItems = marketingSpends.filter(s => s.source === MarketingSpendSource.SITEWEB && filterByDate(s.date_start));
    const ads = adsItems.reduce((a, c) => a + Number(c.amount), 0);

    const delivered = items.filter(i => [SitewebStatus.LIVREE, SitewebStatus.LIVREE_NON_ENCAISSEE].includes(i.status));
    const rawProfit = delivered.reduce((a, c) => {
      const prodCost = Number(c.cout_article) + Number(c.cout_impression);
      return a + (Number(c.prix_vente) - prodCost - Number(c.vendeur_benefice));
    }, 0);
    const returnLoss = items.filter(i => i.status === SitewebStatus.RETOUR).reduce((a, c) => (Number(c.cout_article) + Number(c.cout_impression)), 0);

    const dailyProfit = getDailySeries(delivered, 'date_created', (c) => Number(c.prix_vente) - (Number(c.cout_article) + Number(c.cout_impression)) - Number(c.vendeur_benefice));
    const chartData = dailyProfit.map(p => ({
      date: p.date,
      Profit: p.value,
      Marketing: adsItems.filter(a => a.date_start === p.date).reduce((acc, curr) => acc + Number(curr.amount), 0)
    }));

    return { profitFinal: rawProfit - returnLoss - ads, ads, returnLoss, chartData, count: items.length };
  }, [getCalculatedSiteweb, marketingSpends, dashboardDateStart, dashboardDateEnd]);

  // 🟪 PILLAR: MERCH
  const merchMetrics = useMemo(() => {
    const items = getCalculatedMerch().filter(i => filterByDate(i.created_at));
    const adsItems = marketingSpends.filter(s => s.source === MarketingSpendSource.MERCH && filterByDate(s.date_start));
    const ads = adsItems.reduce((a, c) => a + Number(c.amount), 0);

    const delivered = items.filter(i => [MerchStatus.LIVREE, MerchStatus.LIVREE_NON_ENCAISSEE].includes(i.status));
    const rawProfit = delivered.reduce((a, c) => a + (Number(c.prix_vente) - Number(c.prix_achat)), 0);
    const returnLoss = items.filter(i => i.status === MerchStatus.RETOUR).reduce((a, c) => a + Number(c.prix_achat), 0);

    const chartData = delivered.map(i => ({
      date: i.created_at.split('T')[0],
      Profit: Number(i.prix_vente) - Number(i.prix_achat),
      Marketing: adsItems.find(a => a.date_start === i.created_at.split('T')[0])?.amount || 0
    }));

    return { profitFinal: rawProfit - returnLoss - ads, ads, returnLoss, chartData, count: items.length };
  }, [getCalculatedMerch, marketingSpends, dashboardDateStart, dashboardDateEnd]);

  // 🟩 PILLAR: OFFRES
  const offresMetrics = useMemo(() => {
    const items = offres.filter(i => filterByDate(i.date));
    const adsItems = marketingSpends.filter(s => s.source === MarketingSpendSource.OFFRES && filterByDate(s.date_start));
    const ads = adsItems.reduce((a, c) => a + Number(c.amount), 0);
    const netRevenue = items.reduce((a, c) => a + (c.type === OffreType.REVENUE ? Number(c.montant) : -Number(c.montant)), 0);

    const chartData = items.map(i => ({
      date: i.date,
      Net: i.type === OffreType.REVENUE ? Number(i.montant) : -Number(i.montant),
      Marketing: adsItems.find(a => a.date_start === i.date)?.amount || 0
    }));

    return { profitFinal: netRevenue - ads, ads, chartData, count: items.length };
  }, [offres, marketingSpends, dashboardDateStart, dashboardDateEnd]);

  const globalKPIs = useMemo(() => {
    const cg = getCalculatedGros().filter(i => filterByDate(i.date_created));
    const cs = getCalculatedSiteweb().filter(i => filterByDate(i.date_created));
    const cm = getCalculatedMerch().filter(i => filterByDate(i.created_at));
