import { GoogleGenAI } from "@google/genai";

/**
 * AI Strategic Analyst Backend (MERCHO)
 * Refactored to use the official Google GenAI SDK with gemini-3-pro-preview.
 */
export default async function handler(req, res) {
  if (req.method !== 'POST') {
    res.setHeader('Allow', ['POST']);
    return res.status(405).json({ error: `Method ${req.method} not allowed.` });
  }

  // API Key must be obtained exclusively from environment variables
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    console.error("Critical Error: Missing API_KEY in environment variables.");
    return res.status(500).json({ error: 'Server configuration error: AI service unavailable.' });
  }

  try {
    const { messages, context } = req.body;

    const systemPrompt = `You are MERCHO, a virtual executive finance assistant for an e-commerce printing company.

Role & Scope:
- Analyze provided financial and operational data only.
- Never assume, guess, or hallucinate missing information.
- Operate strictly in read-only advisory mode.

Analysis Focus:
- Sales & revenue trends
- Marketing spend efficiency and ROI
- Charges and cost structure
- Inventory / production investment
- Returns and their impact on profitability
- Cashflow risks and opportunities

Audience & Tone:
- Your audience is the CEO.
- Use a formal, strategic, boardroom-level tone.
- Be concise, precise, and impact-focused.

Output Rules:
- 3 to 5 bullet points maximum
- Each bullet contains:
  • Insight (what is happening)
  • Business implication (why it matters)
  • Actionable recommendation (what to do)
- If data is insufficient, explicitly state the limitation.

Constraints:
- No external knowledge
- No data modification
- No speculation

CURRENT BUSINESS DATA CONTEXT:
${context || 'No data provided.'}`;

    // Initialize Google GenAI with the secure API key
    const ai = new GoogleGenAI({ apiKey });

    // Map conversation history to GenAI format (user/model)
    const contents = messages.map(msg => ({
      role: msg.role === 'assistant' ? 'model' : 'user',
      parts: [{ text: msg.content }]
    }));

    // Call the complex reasoning model
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: contents,
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.3,
        topP: 0.95,
        topK: 40
      },
    });

    // Extract text from response safely using the .text property
    const aiContent = response.text || "MERCHO is currently unable to provide a strategic analysis.";

    // Return response in expected format for the frontend
    return res.status(200).json({
      choices: [
        {
          message: {
            content: aiContent
          }
        }
      ]
    });

  } catch (error) {
    console.error("MERCHO Strategic Backend Error:", error);
    return res.status(500).json({ error: 'Failed to process strategic analysis via GenAI.' });
  }
}

import { GoogleGenAI } from "@google/genai";

/**
 * General Purpose AI Assistant Backend
 * Refactored to use official Google GenAI SDK.
 */
export default async function handler(req, res) {
  if (req.method !== 'POST') {
    res.setHeader('Allow', ['POST']);
    return res.status(405).json({ error: `Method ${req.method} not allowed.` });
  }

  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    return res.status(500).json({ error: "Server configuration error: API Key missing." });
  }

  try {
    const { messages } = req.body;

    const systemPrompt = `You are MERCHO, a virtual executive finance assistant for an e-commerce printing company. Use a formal, boardroom-level tone. Focus on ROI, profitability, and operational efficiency.`;

    // Always use named parameter for apiKey initialization
    const ai = new GoogleGenAI({ apiKey });

    // Format conversation history for GenAI
    const formattedContents = messages.map(m => ({
      role: m.role === 'assistant' ? 'model' : 'user',
      parts: [{ text: m.content || m.text }] // Support both content and text naming conventions
    }));

    // Use gemini-3-flash-preview for general text tasks
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: formattedContents,
      config: {
        systemInstruction: systemPrompt,
        temperature: 0.3,
      },
    });

    // Access .text property directly
    return res.status(200).json({
      choices: [
        {
          message: {
            content: response.text || "Service unavailable."
          }
        }
      ]
    });

  } catch (error) {
    console.error("General AI Assistant Error:", error);
    return res.status(500).json({ error: 'AI routing failure.' });
  }
}
